def load_settings(env):
    """Settings from environment variables. env maps names to strings, like os.environ.

    Flags accept 1/0, true/false, yes/no and on/off in any case; anything else is a mistake and
    must fail loudly. A flag that is not set at all uses its default.
    """
    return {
        "beta_checkout": bool(env.get("BETA_CHECKOUT", False)),
        "send_emails": bool(env.get("SEND_EMAILS", True)),
        "max_upload_mb": int(env.get("MAX_UPLOAD_MB", 25)),
    }

