import unittest

from settings import load_settings


class Regression(unittest.TestCase):
    def test_every_documented_spelling_works(self):
        for raw in ["1", "true", "TRUE", "Yes", "on"]:
            self.assertIs(load_settings({"BETA_CHECKOUT": raw})["beta_checkout"], True, raw)
        for raw in ["0", "false", "False", "NO", "off"]:
            self.assertIs(load_settings({"BETA_CHECKOUT": raw})["beta_checkout"], False, raw)

    def test_unset_flags_use_their_defaults(self):
        settings = load_settings({})
        self.assertIs(settings["beta_checkout"], False)
        self.assertIs(settings["send_emails"], True)
        self.assertEqual(settings["max_upload_mb"], 25)

    def test_a_typo_fails_loudly(self):
        with self.assertRaises(ValueError):
            load_settings({"SEND_EMAILS": "ture"})

