TRUE = {"1", "true", "yes", "on"}
FALSE = {"0", "false", "no", "off"}


def flag(env, name, default):
    """A boolean from an environment variable. bool() cannot do this: every non-empty string is True."""
    raw = env.get(name)
    if raw is None:
        return default
    value = raw.strip().lower()
    if value in TRUE:
        return True
    if value in FALSE:
        return False
    raise ValueError("%s must be one of 1/0, true/false, yes/no, on/off, not %r" % (name, raw))


